  .ts-module-page{min-width:0}.ts-module-header h2{font-size:1.85rem;line-height:1.08}.ts-module-header p{font-size:.95rem;line-height:1.5}.admin-tabs{margin-inline:-2px}.admin-tabs button{min-height:46px;padding:10px 14px;font-size:.95rem}.users-panel{padding:12px!important}.users-table-wrap,.permissions-table-wrap{overflow:visible}.users-table thead,.permissions-table thead{display:none}.users-table,.users-table tbody,.permissions-table,.permissions-table tbody{display:block;width:100%}.users-table tr,.permissions-table tr{display:grid;width:100%;margin-bottom:12px;padding:16px;border:1px solid var(--ts-border);border-radius:16px;background:var(--ts-surface-2);box-shadow:var(--ts-shadow-sm)}.users-table td,.permissions-table td{display:grid!important;grid-template-columns:92px minmax(0,1fr);align-items:center;gap:10px;width:100%!important;min-width:0!important;padding:8px 0!important;border:0!important}.users-table td::before,.permissions-table td::before{content:attr(data-label);color:var(--ts-muted);font-size:.76rem;font-weight:800;text-transform:uppercase;letter-spacing:.04em}.users-table .user-identity{display:block!important;padding-bottom:12px!important;margin-bottom:4px;border-bottom:1px solid var(--ts-border)!important}.users-table .user-identity::before{display:none}.user-identity strong{display:block;font-size:1rem}.user-identity small{margin-top:2px;font-size:.82rem;overflow-wrap:anywhere}.users-table select,.users-table input:not([type=checkbox]){width:100%;min-width:0;min-height:46px;font-size:16px}.users-table .active-cell{grid-template-columns:92px 1fr}.users-table .active-cell input{justify-self:start;width:23px;height:23px}.users-table .user-save-cell,.permissions-table .permission-save{grid-template-columns:1fr;padding-top:12px!important}.users-table .user-save-cell::before,.permissions-table .permission-save::before{display:none}.user-save,.permission-save button{width:100%;min-height:44px}.permissions-grid article{padding:14px!important}.permissions-grid h3{font-size:1.1rem}.permissions-table tr{grid-template-columns:1fr 1fr;gap:4px 12px}.permissions-table td{grid-template-columns:1fr auto;padding:8px!important;border-bottom:1px solid color-mix(in srgb,var(--ts-border) 65%,transparent)!important}.permissions-table .permission-module{grid-column:1/-1;display:block!important;padding:4px 8px 12px!important;font-size:1rem;font-weight:800;border-bottom:1px solid var(--ts-border)!important}.permissions-table .permission-module::before{display:none}.permissions-table td input[type=checkbox]{width:22px;height:22px}.permissions-table .permission-save{grid-column:1/-1;border-bottom:0!important}.permissions-table td::before{font-size:.72rem}
}
